def subtract(a, b):
    # Filter out empty intervals and merge/normalize the input lists
    def merge_intervals(intervals):
        if not intervals:
            return []

        # Filter empty intervals and sort
        valid = [interval for interval in intervals if interval[0] < interval[1]]
        if not valid:
            return []

        valid.sort()

        # Merge overlapping and touching intervals
        merged = [valid[0]]
        for start, end in valid[1:]:
            last_start, last_end = merged[-1]
            if start <= last_end:
                # Overlapping or touching, merge them
                merged[-1] = [last_start, max(last_end, end)]
            else:
                # Disjoint, add as new interval
                merged.append([start, end])

        return merged

    # Merge intervals in both a and b
    a_merged = merge_intervals(a)
    b_merged = merge_intervals(b)

    if not a_merged:
        return []

    if not b_merged:
        return a_merged

    # Subtract b from a
    result = []

    for a_start, a_end in a_merged:
        # For each interval in a, subtract all overlapping intervals from b
        current_ranges = [[a_start, a_end]]

        for b_start, b_end in b_merged:
            new_ranges = []
            for curr_start, curr_end in current_ranges:
                # Check if b interval overlaps with current range
                if b_end <= curr_start or b_start >= curr_end:
                    # No overlap, keep the current range
                    new_ranges.append([curr_start, curr_end])
                else:
                    # There is overlap, potentially split the current range
                    if curr_start < b_start:
                        # Part before b_start
                        new_ranges.append([curr_start, b_start])
                    if curr_end > b_end:
                        # Part after b_end
                        new_ranges.append([b_end, curr_end])
            current_ranges = new_ranges

        result.extend(current_ranges)

    # Merge touching intervals in result
    if not result:
        return []

    result.sort()
    final = [result[0]]
    for start, end in result[1:]:
        last_start, last_end = final[-1]
        if start <= last_end:
            final[-1] = [last_start, max(last_end, end)]
        else:
            final.append([start, end])

    return final

